#Dependencies
import torch
from torch import nn
from PIL import Image
import numpy as np
import urllib


#The Raw Model
#Raw Model
class CifarObjectClassification(nn.Module):
    def __init__(self,**kwargs):
        super(CifarObjectClassification,self).__init__(**kwargs)
        self.conv1 = nn.Conv2d(3,32,kernel_size=3,padding=1,stride=1)
        self.start = nn.Sequential(
            nn.BatchNorm2d(32),
            nn.GELU(),
            nn.Conv2d(32,64,kernel_size=3,padding=1,stride=1),
            nn.MaxPool2d(kernel_size=4)
        )
        self.end = nn.Sequential(
            nn.BatchNorm2d(64),
            nn.GELU(),
            nn.Conv2d(64,128,kernel_size=4,padding=1,stride=1)
        )
        self.out = nn.Linear(6272,10)

    def forward(self,train_images):
        #Shape = b x c x h x w
        train_images = train_images.to(torch.float32)
        x = self.conv1(train_images)
        x = self.start(x)
        x = self.end(x)
        x = x.flatten(1)
        x = self.out(x)
        return x

#Label Dictionary
label_dict_ref = {
    0: 'airplane',
    1: 'automobile',
    2: 'bird',
    3: 'cat',
    4: 'deer',
    5: 'dog',
    6: 'frog',
    7: 'horse',
    8: 'ship',
    9: 'truck'
}

#Applying Pretrained Weights and Forcing model to CPU

# model = CifarObjectClassification()
# model.load_state_dict(torch.load("./models/cifar-10-model.pth",map_location=torch.device("cpu")))


def preprocessImage(img_path):
    img = Image.open(img_path)
    img = img.resize((32,32))
    img = np.array(img)
    img = img/255
    torch_img = torch.from_numpy(img).permute(2,0,1).unsqueeze(0)
    return torch_img

def modelPrediction(img):
    #Img must be a torch tensor of shape - 1 x C x H x W
    model = CifarObjectClassification()
    model.load_state_dict(torch.load("objects_10/models/cifar-10-model.pth",map_location=torch.device("cpu")))
    with torch.no_grad():
        img = img.to("cpu")
        y = model(img)
    result = {
        'Logits':torch.softmax(y[0],dim=0), 
        'Predicted':(y[0].argmax(dim=0)).item(),
        'Verdict':f"It's a {label_dict_ref[y[0].argmax(dim=0).item()]}",
    }
    return result


def getPrediction(img_path):
    img = preprocessImage(img_path)
    result = modelPrediction(img)
    return result['Verdict']


